+    if (options?.allowMissing)
+    {
+      AssertWithinRoot(candidate);
+      return candidate;
+    }
+
+    try
+    {
+      const resolved = await realpath(candidate);
+      AssertWithinRoot(resolved);
+      return resolved;
+    }
+    catch (error)
+    {
+      if (options?.allowMissing && IsWithinRoot(candidate, canonicalRoot))
+      {
+        const parent = path.dirname(candidate);
+        const parentResolved = await realpath(parent);
+        AssertWithinRoot(parentResolved);
+
+        const resolvedCandidate = path.resolve(parentResolved, path.basename(candidate));
+        AssertWithinRoot(resolvedCandidate);
+        return resolvedCandidate;
+      }
+
+      throw error;
+    }
+  }
+
+  return {
+    rootDirectory: path.resolve(rootDirectory),
+    canonicalRoot,
+    ResolveInputPath,
+    ToRootRelativePath,
+    AssertWithinRoot,
+  };
+}

