  "build",
  ".cache",
  "__pycache__",
  ".venv",
  "venv",
  "target",
  "vendor",
  ".next",
  ".turbo",
  "coverage",
  ".pytest_cache",
  ".mypy_cache",
  ".tox",
  "out",
];

